import { InstancedMesh, IcosahedronGeometry, InstancedBufferAttribute, Object3D, Group, Color, DoubleSide, AdditiveBlending, NormalBlending, PlaneGeometry, Mesh } from 'three/webgpu';
import { attribute, uniform, vec3, float, mix, clamp } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'particle-constellation-hero';

  const FIELD_COUNT = 1110;
  const CORE_COUNT = 90;

  // ---------- FIELD PARTICLES ----------
  const fieldGeo = new IcosahedronGeometry(0.012, 0);
  const fieldMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  const uOpacity = attribute('aOpacity');
  fieldMat.colorNode = vec3(0.91, 0.925, 0.945);
  fieldMat.opacityNode = clamp(uOpacity, 0.0, 1.0);

  const fieldMesh = new InstancedMesh(fieldGeo, fieldMat, FIELD_COUNT);
  fieldMesh.name = 'field-particles';

  const fieldAnchors = new Float32Array(FIELD_COUNT * 3);
  const fieldPhases = new Float32Array(FIELD_COUNT);
  const opacityAttr = new Float32Array(FIELD_COUNT);
  const dummy = new Object3D();

  for (let i = 0; i < FIELD_COUNT; i++) {
    // ellipsoidal shell distribution, 6 x 4 x 5, centered at [0,0,-1.5]
    const u = Math.random() * Math.PI * 2;
    const v = Math.acos(2 * Math.random() - 1);
    const r = 0.65 + Math.random() * 0.35;
    const x = 3.0 * r * Math.sin(v) * Math.cos(u);
    const y = 2.0 * r * Math.sin(v) * Math.sin(u);
    const z = -1.5 + 2.5 * r * Math.cos(v);

    fieldAnchors[i * 3] = x;
    fieldAnchors[i * 3 + 1] = y;
    fieldAnchors[i * 3 + 2] = z;
    fieldPhases[i] = Math.random() * Math.PI * 2;

    const t = clampNum((z - 0) / (-5 - 0), 0, 1);
    opacityAttr[i] = mixNum(0.9, 0.15, t);

    dummy.position.set(x, y, z);
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
  }

  fieldGeo.setAttribute('aOpacity', new InstancedBufferAttribute(opacityAttr, 1));
  fieldMesh.instanceMatrix.needsUpdate = true;
  group.add(fieldMesh);

  // ---------- CORE ACCENT PARTICLES ----------
  const coreGeo = new IcosahedronGeometry(0.014, 0);
  const coreMat = new MeshBasicNodeMaterial({ transparent: true, blending: AdditiveBlending, depthWrite: false });
  const pulseUniform = uniform(1.8);
  coreMat.colorNode = vec3(1.0, 0.165, 0.22).mul(pulseUniform);
  coreMat.opacityNode = float(0.95);

  const coreMesh = new InstancedMesh(coreGeo, coreMat, CORE_COUNT);
  coreMesh.name = 'core-particles';

  const coreAnchors = new Float32Array(CORE_COUNT * 3);
  const corePhases = new Float32Array(CORE_COUNT);

  for (let i = 0; i < CORE_COUNT; i++) {
    const u = Math.random() * Math.PI * 2;
    const v = Math.acos(2 * Math.random() - 1);
    const r = Math.random() * 0.5;
    const x = r * Math.sin(v) * Math.cos(u);
    const y = r * Math.sin(v) * Math.sin(u);
    const z = r * Math.cos(v);

    coreAnchors[i * 3] = x;
    coreAnchors[i * 3 + 1] = y;
    coreAnchors[i * 3 + 2] = z;
    corePhases[i] = Math.random() * Math.PI * 2;

    dummy.position.set(x, y, z);
    dummy.scale.setScalar(1);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  group.add(coreMesh);

  function clampNum(v, a, b) { return Math.min(b, Math.max(a, v)); }
  function mixNum(a, b, t) { return a + (b - a) * t; }

  // ---------- TEXT ----------
  const heroText = ctx.fontAtlas.createTextMesh('NOVA ATELIER', {
    family: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.01, lineHeight: 1.02,
    color: '#e8ecf2',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createTextMesh('Precision instruments for the dark hours.', {
    family: 'JetBrains Mono', fontSize: 40, fontWeight: 400, letterSpacing: 0.02, lineHeight: 1.35,
    color: '#e8ecf2',
  });
  subheadText.position.set(0, 0.5 - 0.75, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createTextMesh('EST. 2019 / GENEVA AND KYOTO', {
    family: 'JetBrains Mono', fontSize: 18, fontWeight: 400, letterSpacing: 0.08, lineHeight: 1.4,
    color: '#ff2a38',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // ---------- CINEMATIC PRIMITIVE: particle-emerge ----------
  const emergeTarget = new Group();
  emergeTarget.add(fieldMesh);
  emergeTarget.add(coreMesh);
  group.add(emergeTarget);

  const emergeConfig = (config.cinematicPrimitives || []).find(p => p.name === 'particle-emerge');
  if (emergeConfig && ctx.primitives && ctx.primitives['particle-emerge']) {
    ctx.primitives['particle-emerge'](emergeTarget, emergeConfig.params || { count: 1200, durationMs: 1400 });
  }

  // ---------- AMBIENT DRIFT + CORE PULSE ----------
  let elapsed = 0;
  const driftDummy = new Object3D();

  function tick(deltaSec) {
    elapsed += deltaSec;

    for (let i = 0; i < FIELD_COUNT; i++) {
      const bx = fieldAnchors[i * 3];
      const by = fieldAnchors[i * 3 + 1];
      const bz = fieldAnchors[i * 3 + 2];
      const phase = fieldPhases[i];
      const w = 0.05 * Math.PI * 2;
      const off = 0.04 * Math.sin(elapsed * w + phase);
      driftDummy.position.set(bx + off, by + off * 0.7, bz + off * 0.5);
      driftDummy.scale.setScalar(1);
      driftDummy.updateMatrix();
      fieldMesh.setMatrixAt(i, driftDummy.matrix);
    }
    fieldMesh.instanceMatrix.needsUpdate = true;

    for (let i = 0; i < CORE_COUNT; i++) {
      const bx = coreAnchors[i * 3];
      const by = coreAnchors[i * 3 + 1];
      const bz = coreAnchors[i * 3 + 2];
      const phase = corePhases[i];
      const w = 0.05 * Math.PI * 2;
      const off = 0.04 * Math.sin(elapsed * w + phase);
      driftDummy.position.set(bx + off, by + off * 0.7, bz + off * 0.5);
      driftDummy.scale.setScalar(1);
      driftDummy.updateMatrix();
      coreMesh.setMatrixAt(i, driftDummy.matrix);
    }
    coreMesh.instanceMatrix.needsUpdate = true;

    const pulse = 1.5 + (1.8 - 1.5) * (0.5 + 0.5 * Math.sin(elapsed * 0.1 * Math.PI * 2));
    pulseUniform.value = pulse;
  }

  const tickerFn = (t, deltaMs) => {
    tick((deltaMs || 16.6) / 1000);
  };
  gsap.ticker.add(tickerFn);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    gsap.ticker.remove(tickerFn);
    gsap.killTweensOf(emergeTarget);
    fieldGeo.dispose();
    fieldMat.dispose();
    coreGeo.dispose();
    coreMat.dispose();
    if (heroText.geometry) heroText.geometry.dispose();
    if (heroText.material) heroText.material.dispose();
    if (subheadText.geometry) subheadText.geometry.dispose();
    if (subheadText.material) subheadText.material.dispose();
    if (captionText.geometry) captionText.geometry.dispose();
    if (captionText.material) captionText.material.dispose();
  };

  return group;
}
